package hr.hrg.wyhash;

import java.lang.foreign.MemorySegment;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Asserts the Java port against the reference's vector table — {@code WyhashVectors}, generated by
 * {@code conformance/gen-vectors.zig} from {@code std.hash.Wyhash}.
 *
 * <p>Both the JUnit test and {@code bun wyhash/check-ports.mjs} use this class, so "the Java port passes the
 * vectors" is one implementation of the claim and not two that can drift. It deliberately has no JUnit import:
 * {@code check-ports.mjs} compiles only this class, the generated table and the implementation, which keeps
 * the cross-port check a couple of {@code javac}/{@code java} calls rather than a Maven run.</p>
 *
 * <p><b>The bytes of a {@code text} case are the fixture's UTF-8 encoding.</b> That is what the vector file
 * means by {@code text} (and why the generated table carries hex). Java's {@link Wyhash64#hash(long, String)}
 * hashes a string's <em>internal</em> encoding — Latin-1 or UTF-16 — so for non-ASCII text it is a different
 * byte sequence; the vectors pin the byte sequence, and this check hashes {@code getBytes(UTF_8)}.</p>
 */
final class WyhashVectorCheck {

    private WyhashVectorCheck() {
    }

    /**
     * Every case: the one-shot {@code byte[]} value against the reference, the {@link MemorySegment} path
     * against the {@code byte[]} path, and — for the cases large enough to have real blocks and a tail — the
     * streaming form against the one-shot one.
     *
     * @return a report of the failures, empty when every case agrees
     */
    static String checkAll() {
        List<String> failures = new ArrayList<>();
        int checked = 0;
        int seeded = 0;
        int streamed = 0;

        for (WyhashVectors.Vector vector : WyhashVectors.CASES) {
            byte[] bytes = vector.bytes();
            String actual = Wyhash64.hex(Wyhash64.hash(vector.seed(), bytes));
            if (!actual.equals(vector.expected())) {
                failures.add(vector.label() + ": byte[] gave " + actual + ", reference says " + vector.expected());
            }

            // The segment path must be the same bytes, not merely "a hash".
            String throughSegment = Wyhash64.hex(Wyhash64.hash(vector.seed(), MemorySegment.ofArray(bytes)));
            if (!throughSegment.equals(actual)) {
                failures.add(vector.label() + ": MemorySegment gave " + throughSegment + ", byte[] gave " + actual);
            }

            // Streaming, in chunks that land on and inside the 48-byte block boundary, on every case big
            // enough for the block and tail paths to matter.
            if (bytes.length > 16) {
                Wyhash64.Streaming streaming = new Wyhash64.Streaming(vector.seed());
                int chunk = 7;
                for (int at = 0; at < bytes.length; at += chunk) {
                    streaming.update(bytes, at, Math.min(chunk, bytes.length - at));
                }
                String streamedValue = Wyhash64.hex(streaming.finalHash());
                if (!streamedValue.equals(actual)) {
                    failures.add(vector.label() + ": streaming gave " + streamedValue + ", one-shot gave " + actual);
                }
                streamed++;
            }

            // A text case is its UTF-8 bytes; a port that hashed the string's internal encoding instead would
            // pass nothing here for non-ASCII text, which is the point of pinning bytes.
            if (vector.label().startsWith("utf8") && !new String(bytes, StandardCharsets.UTF_8).isBlank()) {
                String fromString = Wyhash64.hex(Wyhash64.hash(vector.seed(),
                        new String(bytes, StandardCharsets.UTF_8).getBytes(StandardCharsets.UTF_8)));
                if (!fromString.equals(actual)) {
                    failures.add(vector.label() + ": a UTF-8 round trip gave " + fromString);
                }
            }

            if (vector.seed() != 0) {
                seeded++;
            }
            checked++;
        }

        if (checked < 40) {
            failures.add("the vector table holds only " + checked + " cases; the reference generates more");
        }
        if (seeded < 5) {
            failures.add("the vector table holds only " + seeded + " seeded cases; a port could ignore its seed");
        }
        if (failures.isEmpty()) {
            return "";
        }
        return String.join("\n  ", failures) + "\n  (" + checked + " cases checked, " + streamed
                + " also streamed, " + seeded + " seeded)";
    }

    /** Runs the check and exits non-zero with a report when it fails. */
    public static void main(String[] args) {
        String failures = checkAll();
        if (!failures.isEmpty()) {
            System.err.println("wyhash Java port disagrees with the reference vectors:\n  " + failures);
            System.exit(1);
        }
        int text = 0;
        int pattern = 0;
        for (WyhashVectors.Vector vector : WyhashVectors.CASES) {
            if (vector.isPattern()) {
                pattern++;
            } else {
                text++;
            }
        }
        System.out.println("ok " + WyhashVectors.CASES.length + " reference case(s) (" + text + " byte sequences, "
                + pattern + " patterns), plus the MemorySegment and streaming paths");
    }
}